package project.study.study_project.report.domain;

/**
 * 문제 오류 제보의 사유 — <b>자유 입력이 아니라 코드</b>다(V17).
 *
 * <h2>왜 코드로 받나</h2>
 *
 * <p>이 값은 화면에만 쓰이는 것이 아니라 <b>다음 문제 생성 프롬프트로 들어간다</b>
 * (인정된 제보 → {@code generated/_rejection-notes.json} → 배치, docs/14). 같은 지적이 매번
 * 다른 문장으로 쌓이면 되먹임이 흩어져 "이 실수가 반복된다"는 신호가 되지 못한다.
 * 검수 화면이 거절 사유를 칩으로 고르게 만든 것과 같은 판단이다
 * ({@code admin/llm.html}의 {@code REJECT_REASONS} 주석).
 *
 * <p>그때그때의 사정은 {@link ProblemReport#getDetail()}이 받는다 — 코드가 뼈대,
 * 상세가 살이다. 상세를 필수로 만들지 않은 이유는 <b>제보의 문턱을 낮추는 것</b>이 이 기능의
 * 목적이기 때문이다. 한 줄 쓰기가 귀찮아 그냥 지나치면 결함은 영영 안 알려진다.
 *
 * <h2>목록을 이렇게 고른 근거</h2>
 *
 * <p>"검수를 통과했는데도 남는 결함"만 담았다. 중복 출제나 난이도 불일치처럼 검수 단계에서
 * 걸러지는 것은 넣지 않았다 — 푸는 사람이 판단할 수 있는 자리가 아니고, 넣으면 목록이 길어져
 * 고르는 데 시간이 걸린다. 다섯 개는 한눈에 읽힌다.
 */
public enum ReportReason {

    /** 가장 무거운 제보. 이게 사실이면 그 문제는 학습자에게 <b>틀린 지식을 가르친다</b>. */
    WRONG_ANSWER("정답으로 표시된 보기가 실제로는 틀렸다"),

    /** 정답이 둘로 읽히거나 보기끼리 겹치는 경우 — 거절 사유 칩에도 같은 항목이 있다. */
    AMBIGUOUS("보기가 서로 겹치거나 정답이 둘로 읽힌다"),

    /** 해설이 다른 문제의 것이거나 지문과 어긋나는 경우. 채점은 맞는데 설명이 안 맞는 상태. */
    EXPLANATION_MISMATCH("해설이 이 문제와 맞지 않는다"),

    /** 근거 개념 문서와 내용이 어긋나는 경우 — 둘 중 하나가 틀렸다는 뜻이라 값진 신호다. */
    CONTRADICTS_DOCUMENT("근거 개념 문서와 내용이 다르다"),

    /** 오타·깨진 표기. 가벼워 보이지만 코드 블록이 깨지면 문제 자체를 못 푸는 경우가 있다. */
    TYPO("오타나 깨진 표기가 있다"),

    /** 위 어디에도 안 들어가는 것. 이 값을 고르면 화면이 상세 입력을 <b>권한다</b>(강제하진 않는다). */
    OTHER("그 밖의 문제");

    private final String label;

    ReportReason(String label) {
        this.label = label;
    }

    /**
     * 사람이 읽는 문구이자 <b>프롬프트에 실려 가는 문장</b>. 화면과 프롬프트가 같은 문자열을
     * 쓰는 이유: 두 곳에 따로 적으면 화면 문구만 다듬어졌을 때 되먹임 쪽이 조용히 옛말을 하게 된다.
     */
    public String getLabel() {
        return label;
    }
}
